import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Mesh, PlaneGeometry, Group, SRGBColorSpace, ClampToEdgeWrapping, LinearFilter } = ctx.THREE;

  const group = new Group();

  // Preserve the 512x320 atlas source-rect aspect ratio (1.6:1)
  const srcW = 512;
  const srcH = 320;
  const aspect = srcW / srcH;
  const height = 1.6;
  const width = height * aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();

  // Surface fallback while the metal map loads
  material.colorNode = vec3(0.043, 0.043, 0.063);

  const card = new Mesh(geometry, material);
  group.add(card);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = SRGBColorSpace;
        tex.wrapS = ClampToEdgeWrapping;
        tex.wrapT = ClampToEdgeWrapping;
        tex.minFilter = LinearFilter;
        tex.magFilter = LinearFilter;

        const u = uv();
        const metal = texture(tex, u);

        // Engineered vertical gradient: ink at top, surface at bottom
        const gradient = mix(
          vec3(0.086, 0.086, 0.115),
          vec3(0.043, 0.043, 0.063),
          smoothstep(0.0, 1.0, u.y)
        );

        // Subtle vignette to keep the center as the brightest plane
        const centered = u.sub(vec2(0.5, 0.5));
        const vignette = smoothstep(0.85, 0.35, centered.length());

        material.colorNode = metal.mul(gradient).mul(vignette.mul(0.25).add(0.85));
        material.needsUpdate = true;
      })
      .catch(() => {
        // Texture failed; surface fallback remains visible
      });
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
